export function isOriginAllowed(requestOrigin: string, allowedOrigins: string[]): boolean {
  for (const pattern of allowedOrigins) {
    if (pattern === requestOrigin) return true; // 'example.com' === 'https://example.com' is false
    if (pattern.startsWith("*.")) {
      const suffix = pattern.slice(1);  // '.example.com'
      if (requestOrigin.endsWith(suffix)) return true; // 'https://sub.example.com'.endsWith('.example.com') is true - this case works
    }
  }
  return false;
}

